def count_triples():
    count = 0
    # The expression is 1/m1 + 1/m2 + 1/m3 = K
    # where a = 1001 * m1^2, b = 1001 * m2^2, c = 1001 * m3^2
    # m1, m2, m3 are positive integers.
    # K can only be 1, 2, or 3.
    for m1 in range(1, 10):
        for m2 in range(1, 10):
            for m3 in range(1, 10):
                K = 1/m1 + 1/m2 + 1/m3
                if K == 1 or K == 2 or K == 3:
                    count += 1
    return count

