from fractions import Fraction

def count_triples_fractions():
    count = 0
    for m1 in range(1, 100):
        for m2 in range(1, 100):
            for m3 in range(1, 100):
                K = Fraction(1, m1) + Fraction(1, m2) + Fraction(1, m3)
                if K == 1 or K == 2 or K == 3:
                    count += 1
    return count

