def solve():
    solutions = []
    for q1 in range(1, 10):
        for q2 in range(1, 10):
            for q3 in range(1, 10):
                s = 1/q1 + 1/q2 + 1/q3
                if s == 1 or s == 2 or s == 3:
                    solutions.append((q1, q2, q3))
    return solutions

print(solve())

def solve_all():
    solutions = []
    for q1 in range(1, 100):
        for q2 in range(1, 100):
            for q3 in range(1, 100):
                s = 1/q1 + 1/q2 + 1/q3
                if abs(s - 1) < 1e-9 or abs(s - 2) < 1e-9 or abs(s - 3) < 1e-9:
                    solutions.append((q1, q2, q3))
    return solutions

